from pathlib import Path

p = Path("MainActivity.kt")
s = p.read_text(encoding="utf-8")
state_anchor = '        var monthToMonthComparison by remember { mutableStateOf<StoredMonthToMonthComparison?>(null) }'
state_insert = state_anchor + '''\n        var smsConversionSummary by remember { mutableStateOf<SmsConversionSummary?>(null) }\n        var smsConversionLoading by remember { mutableStateOf(false) }\n        var showSmsConversionDevices by remember { mutableStateOf(false) }'''
if "var smsConversionSummary by remember" not in s:
    if state_anchor not in s: raise SystemExit("MOM state insertion anchor not found")
    s = s.replace(state_anchor, state_insert, 1)
load_anchor = '        fun openMonthToMonthSearchDetail(hit: MonthToMonthSearchHit) {'
load_insert = '''        LaunchedEffect(showMonthToMonthComparison, activeProfileId) {\n            if (!showMonthToMonthComparison) return@LaunchedEffect\n            smsConversionLoading = true\n            val codes = savedMyDevices()\n            val next = withContext(Dispatchers.IO) {\n                val events = buildList {\n                    addAll(deviceSmsHistoryStore.allDailySnapshots())\n                    addAll(partnerSmsHistoryStore.allDailySnapshots())\n                }\n                SmsConversionMetrics.calculate(events, codes, YearMonth.now())\n            }\n            smsConversionSummary = next\n            smsConversionLoading = false\n        }\n\n''' + load_anchor
if "SmsConversionMetrics.calculate" not in s:
    if load_anchor not in s: raise SystemExit("MOM conversion loader insertion anchor not found")
    s = s.replace(load_anchor, load_insert, 1)
ui_anchor = '                        if (monthToMonthStaffSearchAllowed()) {'
ui_insert = '''                        // Current-calendar-month SMS conversion; isolated from protected payment/MOM calculations.\n                        val conversion = smsConversionSummary\n                        AuroraGlassCard(Modifier.fillMaxWidth(), AuroraCyan) {\n                            Text("CONVERSION • THIS MONTH", style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.ExtraBold, color = MaterialTheme.colorScheme.primary)\n                            Text("${store.getSetting(SETTING_MY_DEVICES_USER_TYPE).orEmpty().ifBlank { "YOUR" }.uppercase(Locale.US)} CONVERSION", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.ExtraBold)\n                            Text("Based on the latest successful SMS Checker MTD and Active return for each saved device this calendar month.", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant)\n                            if (smsConversionLoading) {\n                                Spacer(Modifier.height(8.dp))\n                                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n                                    CircularProgressIndicator(Modifier.size(18.dp), strokeWidth = 2.dp)\n                                    Text("Calculating current-month conversion…", style = MaterialTheme.typography.bodySmall)\n                                }\n                            } else if (conversion == null || conversion.deviceCount == 0) {\n                                Text("No devices are assigned to this profile yet.", style = MaterialTheme.typography.bodySmall)\n                            } else {\n                                Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {\n                                    Column(Modifier.weight(1f)) { Text("MTD", style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant); Text(conversion.mtd.toString(), style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.ExtraBold) }\n                                    Column(Modifier.weight(1f)) { Text("ACTIVE", style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant); Text(conversion.active.toString(), style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.ExtraBold) }\n                                    Column(Modifier.weight(1f)) { Text("LOSS", style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant); Text(conversion.loss.toString(), style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.ExtraBold, color = MaterialTheme.colorScheme.error) }\n                                    Column(Modifier.weight(1f)) { Text("CONVERSION", style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant); Text("${String.format(Locale.US, "%.1f", conversion.conversionPercent)}%", style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.ExtraBold, color = MaterialTheme.colorScheme.primary) }\n                                }\n                                Text("Results available for ${conversion.devicesWithResults} of ${conversion.deviceCount} devices.", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant)\n                                TextButton(onClick = { showSmsConversionDevices = !showSmsConversionDevices }) { Text(if (showSmsConversionDevices) "Hide device conversion" else "View device conversion") }\n                                if (showSmsConversionDevices) {\n                                    HorizontalDivider()\n                                    conversion.rows.forEach { row ->\n                                        Row(Modifier.fillMaxWidth().padding(vertical = 5.dp), verticalAlignment = Alignment.CenterVertically) {\n                                            Column(Modifier.weight(1.4f)) {\n                                                Text(row.code, fontWeight = FontWeight.Bold, style = MaterialTheme.typography.bodySmall)\n                                                Text(if (row.mtd == null) "No current-month SMS result" else "MTD ${row.mtd} • Active ${row.active}", style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant)\n                                            }\n                                            Column(horizontalAlignment = Alignment.End) {\n                                                Text(if (row.loss == null) "—" else "Loss ${row.loss}", fontWeight = FontWeight.SemiBold, style = MaterialTheme.typography.bodySmall)\n                                                Text(if (row.conversionPercent == null) "—" else "${String.format(Locale.US, "%.1f", row.conversionPercent)}%", style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.primary)\n                                            }\n                                        }\n                                    }\n                                }\n                            }\n                        }\n\n''' + ui_anchor
if "CONVERSION • THIS MONTH" not in s:
    if ui_anchor not in s: raise SystemExit("MOM conversion UI insertion anchor not found")
    s = s.replace(ui_anchor, ui_insert, 1)
p.write_text(s, encoding="utf-8")
print("Added current-month SMS Conversion summary and per-device breakdown to MOM.")
